#!/bin/zsh
# CI suite runner (generated by tools/mac/ci.py). Reads ci/suites.txt: one suite per line, "name" or
# "name KEY=VALUE ...". Runs each against the release app with no window shown; timings are informative only.
set -u
zmodload zsh/datetime  # EPOCHREALTIME
out=${1:?out}; mkdir -p $out
disp=${out:h}/display  # the probe and its record, made by "ci/display.sh set" before the build
bin=build/OrganicShell.app/Contents/MacOS/OrganicShell
printf 'suite\texit\tseconds\n' > $out/summary.tsv
while IFS= read -r line; do
  [[ -z $line || $line == \#* ]] && continue
  name=${line%% *}; envs=(); [[ $line == *" "* ]] && envs=(${=${line#* }})
  # CI_DISPLAY=reduce-motion,reduce-transparency (decision #173): this one suite runs with those system switches on;
  # every other suite runs with both off. A suite whose switch did not take is not run (exit 97, no total: a crash).
  display=""; for e in $envs; do [[ $e == CI_DISPLAY=* ]] && display=${e#CI_DISPLAY=}; done
  start=$EPOCHREALTIME
  if [[ -n $display ]] && ! zsh ci/display.sh reduce $disp $display > $out/$name.log 2>&1; then
    code=97
  elif [[ ${line#* } == \!* ]]; then
    mkdir -p $out/$name
    ( eval "${${line#* }#\!}" ) > $out/$name.log 2>&1; code=$?
  elif [[ $name == selftest ]]; then
    env $envs zsh scripts/selftest.sh $out/$name > $out/$name.log 2>&1; code=$?
  else
    mkdir -p $out/$name
    env $envs $bin --selftest $out/$name > $out/$name.log 2>&1; code=$?
  fi
  secs=$(( EPOCHREALTIME - start ))
  if [[ -n $display ]]; then
    # Back to normal before anything else runs; if that fails, later suites would silently take the reduced branch.
    zsh ci/display.sh normal $disp || { cp $disp/display.txt $out/display.txt; echo "display: could not switch back after $name"; exit 1; }
  fi
  printf '%s\t%d\t%.1f\n' $name $code $secs >> $out/summary.tsv
  echo "== $name exit $code in ${secs%.*} s"; tail -40 $out/$name.log | grep -E '^selftest|^  |finding|FAIL|PASS|pass|fail' | head -60
done < ci/suites.txt
[[ -f $disp/display.txt ]] && cp $disp/display.txt $out/display.txt
# The job fails only when a suite that counts on CI is worse than the HEAD baseline (ci/evaluate.py, ci/baseline.json);
# suite exits alone never fail it, so informational and VM-only findings send no failure mail.
python3 ci/evaluate.py $out ci/baseline.json
